/* @lc app=leetcode id=3354 lang=kotlin */ class Solution { fun sim(nums: IntArray, s: Int, d: Int): Boolean = nums.copyOf().let { a -> generateSequence(s to d) { (p, dir) -> if (p !in a.indices) null else if (a[p] == 0) p + dir to dir else a.set(p, a[p] - 1).let { p - dir to -dir } }.count().let { a.all { it == 0 } } } fun countValidSelections(nums: IntArray): Int = nums.indices.filter { nums[it] == 0 }.sumOf { s -> listOf(-1, 1).count { d -> sim(nums, s, d) } } }